function countAlternatingSubarrays(nums) {
  let total = 0;
  let ending = 0;

  for (let i = 0; i < nums.length; i++) {
    if (i > 0 && nums[i] !== nums[i - 1]) {
      ending++;
    } else {
      ending = 1;
    }
    total += ending;
  }
  return total;
}

