function countAlternatingSubarrays(nums) {
  // Check every subarray [start..end] pair by pair.
  let count = 0;
  for (let start = 0; start < nums.length; start++) {
    for (let end = start; end < nums.length; end++) {
      let ok = true;
      for (let p = start + 1; p <= end; p++) if (nums[p] === nums[p - 1]) ok = false;
      if (ok) count++;
    }
  }
  return count;
}

