function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const mode = Math.floor(rand() * 4);
  const flip = mode === 0 ? 0.5 : mode === 1 ? 0.9 : mode === 2 ? 0.15 : 1;
  const nums = [rand() < 0.5 ? 0 : 1];
  for (let i = 1; i < n; i++) {
    nums.push(rand() < flip ? 1 - nums[i - 1] : nums[i - 1]);
  }
  return [nums];
}
